import os
from django.conf import settings
from django.core.mail import mail_managers, mail_admins, get_connection
from django.core.mail.backends.dummy import EmailBackend
from django.core.exceptions import ImproperlyConfigured

# Use dummy backend to avoid sending actual emails
class MyDummyBackend(EmailBackend):
    def send_messages(self, email_messages):
        self.sent_messages = list(email_messages)
        return len(self.sent_messages)

connection = MyDummyBackend()

def test_mail_admins(admins_setting):
    if not settings.configured:
        settings.configure(
            ADMINS=admins_setting,
            SERVER_EMAIL='admin@example.com',
            EMAIL_SUBJECT_PREFIX='[Django] ',
        )
    else:
        settings.ADMINS = admins_setting

    try:
        mail_admins('Test Subject', 'Test Message', connection=connection)
        print(f"SUCCESS for ADMINS={admins_setting}")
    except ImproperlyConfigured as e:
        print(f"EXPECTED ImproperlyConfigured for ADMINS={admins_setting}: {e}")
    except Exception as e:
        print(f"UNEXPECTED exception for ADMINS={admins_setting}: {type(e).__name__}: {e}")

def test_mail_managers(managers_setting):
    if not settings.configured:
        settings.configure(
            MANAGERS=managers_setting,
            SERVER_EMAIL='admin@example.com',
            EMAIL_SUBJECT_PREFIX='[Django] ',
        )
    else:
        settings.MANAGERS = managers_setting

    try:
        mail_managers('Test Subject', 'Test Message', connection=connection)
        print(f"SUCCESS for MANAGERS={managers_setting}")
    except ImproperlyConfigured as e:
        print(f"EXPECTED ImproperlyConfigured for MANAGERS={managers_setting}: {e}")
    except Exception as e:
        print(f"UNEXPECTED exception for MANAGERS={managers_setting}: {type(e).__name__}: {e}")

# Test cases
# Correct format
test_mail_admins([('Admin', 'admin@example.com')])
test_mail_managers([('Manager', 'manager@example.com')])

# Incorrect format: list of strings
test_mail_admins(['admin@example.com'])
test_mail_managers(['manager@example.com'])

# Incorrect format: list of single-element tuples
test_mail_admins([('admin@example.com',)])
test_mail_managers([('manager@example.com',)])

# Incorrect format: not a list of tuples
test_mail_admins([123])
test_mail_managers([123])
