import django
from django.conf import settings

settings.configure(
    TEMPLATES=[{
        'BACKEND': 'django.template.backends.django.DjangoTemplates',
        'APP_DIRS': True,
        'OPTIONS': {},
    }],
)
django.setup()

from django.template import Template, Context

def test_non_existent_variable():
    print("Testing non-existent variable...")
    t = Template("{{ foo }}")
    c = Context({})
    try:
        result = t.render(c)
        print(f"Result: {repr(result)}")
    except Exception as e:
        print(f"Exception: {type(e).__name__}: {e}")

def test_method_on_non_existent_variable():
    print("\nTesting method on non-existent variable...")
    t = Template("{{ foo.count }}")
    c = Context({})
    try:
        result = t.render(c)
        print(f"Result: {repr(result)}")
    except Exception as e:
        print(f"Exception: {type(e).__name__}: {e}")

def test_include_non_existent_variable():
    print("\nTesting include with non-existent variable...")
    # Simulating: {% include 'second.html' with bar=foo %} and then {{ bar.count }}
    # If foo is non-existent, bar becomes "".
    t = Template("{{ bar.count }}")
    c = Context({'bar': ""})
    try:
        result = t.render(c)
        print(f"Result: {repr(result)}")
    except Exception as e:
        print(f"Exception: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_non_existent_variable()
    test_method_on_existent_variable = test_method_on_non_existent_variable() # wait, typo here but not important
    test_include_non_existent_variable()
