from sympy.core.power import integer_nthroot

def isqrt_fixed(n):
    """Return the largest integer less than or equal to sqrt(n)."""
    if n < 17984395633462800708566937239552:
        s = int(_sqrt(n))
        if s*s <= n < (s+1)*(s+1):
            return s
    return integer_nthroot(int(n), 2)[0]

def isqrt_original(n):
    if n < 17984395633462800708566937239552:
        return int(_sqrt(n))
    return integer_nthroot(int(n), 2)[0]

n1 = 4503599761588224
print(f"n1 = {n1}, original = {isqrt_original(n1)}, fixed = {isqrt_fixed(n1)}, correct = 67108864")

n2 = 9999999999999999
print(f"n2 = {n2}, original = {isqrt_original(n2)}, fixed = {isqrt_fixed(n2)}, correct = 99999999")

# Test some other values
import random
for _ in range(1000):
    n = random.getrandbits(100)
    if isqrt_original(n) != isqrt_fixed(n):
        # We found a case where original was wrong (or fixed is wrong, but fixed uses integer_nthroot as fallback)
        # Verify with integer_nthroot
        expected = integer_nthroot(n, 2)[0]
        print(f"n = {n}, original = {isqrt_original(n)}, fixed = {isqrt_fixed(n)}, expected = {expected}")
