from django.db import models

class ParentModel(models.Model):
    id = models.BigIntegerField(primary_key=True)

    class Meta:
        app_label = '__main__'

class ChildModel(ParentModel):
    pass

    class Meta:
        app_label = '__main__'

# Create tables
from django.db import connection
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(ParentModel)
    schema_editor.create_model(ChildModel)

def test_force_insert():
    connection.queries_log.clear()

    # Given
    child = ChildModel(id=1)

    # When
    child.save(force_insert=True)

    # Then
    queries = [q['sql'] for q in connection.queries]
    print("Queries executed:")
    for i, q in enumerate(queries):
        print(f"{i}: {q}")

    # Check for any query that looks like it's coming from _do_update on the parent table
    # For our ParentModel, _do_update will call .exists() because it has no non-pk fields.
    # This results in a SELECT query.
    parent_table = '__main___parentmodel'
    update_or_exists_parent = any(f"SELECT 1 AS \"a\" FROM {parent_table}" in q for q in queries)

    if update_or_exists_parent:
        print("\nISSUE REPRODUCED: UPDATE or EXISTS query found for parent model even with force_insert=True")
    else:
        print("\nISSUE NOT REPRODUCED: No UPDATE or EXISTS query found for parent model")

if __name__ == "__main__":
    test_force_insert()
