    def __getstate__(self):
        state = self.__dict__.copy()
        func = state['func']
        if hasattr(func, 'view_class'):
            # CBV
            state['_func_reconstruct'] = ('cbv', func.view_class, func.view_initkwargs)
        elif isinstance(func, functools.partial):
            # Partial
            state['_func_reconstruct'] = ('partial', func.func, func.args, func.keywords)
        elif hasattr(func, '__module__') and hasattr(func, '__name__'):
            # FBV
            state['_func_reconstruct'] = ('fbv', func.__module__, func.__name__)
        else:
            # Unknown
            state['_func_reconstruct'] = ('unknown', None, None)

        del state['func']
        return state

    def __setstate__(self, state):
        reconstruct = state.pop('_func_reconstruct', None)
        if reconstruct:
            kind, *args = reconstruct
            if kind == 'cbv':
                view_class, initkwargs = args
                state['func'] = view_class.as_view(**initkwargs)
            elif kind == 'partial':
                f, a, k = args
                state['func'] = functools.partial(f, *a, **k)
            elif kind == 'fbv':
                module_name, func_name = args
                try:
                    module = import_module(module_name)
                    state['func'] = getattr(module, func_name)
                except (ImportError, AttributeError):
                    state['func'] = None
            else:
                state['func'] = None

        self.__dict__.update(state)
