class MyModel(Model):
    class Meta:
        app_label = 'myapp'

class OtherModel(Model):
    class Meta:
        app_label = 'otherapp'

class MockAny:
    def __eq__(self, other):
        print("MockAny.__eq__ called")
        return True

def test_eq():
    model_instance = MyModel()
    any_instance = MockAny()

    print("Test 1: Comparing model_instance == MockAny")
    result1 = (model_instance == any_instance)
    print(f"Result: {result1}")
    if result1:
        print("SUCCESS: Model == MockAny returned True")
    else:
        print("FAILURE: Model == MockAny returned False")

    print("\nTest 2: Comparing model_instance == different model")
    other_model_instance = OtherModel()
    result2 = (model_instance == other_model_instance)
    print(f"Result: {result2}")
    if not result2:
        print("SUCCESS: Model == DifferentModel returned False")
    else:
        print("FAILURE: Model == DifferentModel returned True")

if __name__ == "__main__":
    test_eq()
